/* Ordem de fabricação em PDF, gerada no navegador sem enviar dados a terceiros. */
(function(root){
'use strict';
const F=root.EngefexFactoryFlow,M=root.EngefexFactoryModel;
function rows(order,onlyRemaining=false){return order.parts.filter(p=>M.num(p.planned)>0).map(p=>{let planned=M.num(p.planned),done=Math.min(planned,...F.route(order,p).map(k=>F.total(order,p,k)));return {...p,planned,remaining:Math.max(0,planned-done),operations:F.route(order,p).map(k=>F.stages.find(([s])=>s===k)[1]).join(' / ')}}).filter(p=>!onlyRemaining||p.remaining>1e-8)}
async function generate(order,project,opts={}){
 if(!root.PDFLib)throw Error('Gerador de PDF indisponível. Atualize o aplicativo.');
 const list=rows(order,opts.onlyRemaining);if(!list.length)throw Error(opts.onlyRemaining?'Todas as peças estão concluídas. Não há saldo para emitir.':'Cadastre peças com quantidade prevista antes de gerar a ordem.');
 if(!opts.logoBytes)throw Error('O logotipo da Engefex não foi carregado. Tente novamente.');
 const {PDFDocument,StandardFonts,rgb}=root.PDFLib,pdf=await PDFDocument.create(),font=await pdf.embedFont(StandardFonts.Helvetica),bold=await pdf.embedFont(StandardFonts.HelveticaBold),logo=await pdf.embedPng(opts.logoBytes),blue=rgb(.08,.28,.76),ink=rgb(.10,.14,.21),muted=rgb(.35,.41,.49),line=rgb(.82,.86,.91),light=rgb(.94,.96,.99),jobs=[];
 const date=opts.now||new Date(),issued=date.toLocaleDateString('pt-BR'),number='OF-'+(project.code||order.number||'OBRA'),W=841.89,H=595.28,L=36,R=W-36,B=42,lh=11;
 const num=n=>new Intl.NumberFormat('pt-BR',{maximumFractionDigits:3}).format(n),label=v=>String(v??'').replace(/\r/g,'');let page,y;
 function measure(t,size,b=false){try{return (b?bold:font).widthOfTextAtSize(t,size)}catch{if(!root.document)throw Error('O texto contém caracteres que precisam do navegador para renderizar.');let c=root.document.createElement('canvas').getContext('2d');c.font=(b?'bold ':'')+size+'px Arial';return c.measureText(t).width}}
 function text(t,x,baseline,size=8.5,b=false,color=ink){t=label(t);try{(b?bold:font).encodeText(t);page.drawText(t,{x,y:baseline,size,font:b?bold:font,color})}catch{let target=page;const c=root.document.createElement('canvas'),ctx=c.getContext('2d'),scale=3;ctx.font=(b?'bold ':'')+size*scale+'px Arial';c.width=Math.ceil(ctx.measureText(t).width)+6;c.height=Math.ceil(size*scale*1.6);ctx.font=(b?'bold ':'')+size*scale+'px Arial';ctx.fillStyle='#192435';ctx.fillText(t,0,size*scale);jobs.push(pdf.embedPng(c.toDataURL('image/png')).then(img=>target.drawImage(img,{x,y:baseline-(c.height/scale-size),width:c.width/scale,height:c.height/scale})))}}
 function wrap(value,width,size=8.5,b=false){let out=[];for(let para of label(value).split('\n')){let current='';for(let word of para.split(/\s+/)){if(!word)continue;if(measure(word,size,b)>width){if(current){out.push(current);current=''}let piece='';for(let ch of word){if(piece&&measure(piece+ch,size,b)>width){out.push(piece);piece=''}piece+=ch}current=piece;continue}let next=current?current+' '+word:word;if(current&&measure(next,size,b)>width){out.push(current);current=word}else current=next}out.push(current)}return out.length?out:['']}
 function newPage(){page=pdf.addPage([W,H]);page.drawImage(logo,{x:L,y:H-78,width:72,height:56});text('ENGEFEX',L+88,H-37,15,true);text('ENGENHARIA & ESTRUTURAS METÁLICAS',L+88,H-51,8.5,false,muted);text('ORDEM DE FABRICAÇÃO',L+88,H-70,14,true,blue);text(number,R-measure(number,11,true),H-37,11,true);text('Emissão: '+issued,R-measure('Emissão: '+issued,8),H-53,8,false,muted);text('Revisão: '+(order.revision||'Não informada'),R-measure('Revisão: '+(order.revision||'Não informada'),8),H-67,8,false,muted);page.drawLine({start:{x:L,y:H-89},end:{x:R,y:H-89},thickness:1.5,color:blue});y=H-108}
 function block(title,value){let lines=wrap(title+': '+(value||'Não informado'),R-L,8.5);for(let s of lines){if(y<B+20)newPage();text(s,L,y,8.5);y-=12}y-=3}
 function pair(left,right){let columns=[wrap(left,((R-L)-24)/2,8.5),wrap(right,((R-L)-24)/2,8.5)],count=Math.max(...columns.map(a=>a.length));for(let i=0;i<count;i++){if(y<B+20)newPage();text(columns[0][i]||'',L,y,8.5);text(columns[1][i]||'',L+(R-L+24)/2,y,8.5);y-=12}y-=4}
 const dateText=v=>v?String(v).replace(/^(\d{4})-(\d{2})-(\d{2})$/,'$3/$2/$1'):'Não informado';
 newPage();pair('Obra: '+[project.code,project.name].filter(Boolean).join(' - '),'Cliente: '+(project.client||'Não informado'));pair('Local: '+(project.location||'Não informado'),'Responsável: '+(order.owner||'Não informado'));pair('Projeto: '+(order.workflow.profile.drawing||'Não informado'),'Prazo: '+dateText(order.start)+' a '+dateText(order.due));block('Escopo',order.workflow.profile.scope);pair('Materiais / aços: '+(order.workflow.profile.steel||'Não informado'),'Tratamento / cor: '+[{painted:'Pintura',galvanized:'Galvanização',none:'Sem tratamento nesta fabricação'}[order.workflow.profile.coating],order.workflow.profile.color].filter(Boolean).join(' - '));if(order.workflow.profile.notes)block('Instruções',order.workflow.profile.notes);block('Conteúdo',opts.onlyRemaining?'Somente peças com saldo a fabricar':'Relação completa de peças com quantidade prevista');
 const widths=[.07,.23,.22,.08,.06,.08,.26].map(n=>n*(R-L)),headers=['Marca','Peça / grupo / observações','Perfil / dimensões','Previsto','Un.','Falta','Operações previstas'];
 function tableHead(){if(y<B+35)newPage();page.drawRectangle({x:L,y:y-20,width:R-L,height:20,color:light});let x=L;headers.forEach((h,i)=>{text(h,x+5,y-13,8,true);x+=widths[i]});y-=20}
 tableHead();
 for(let [itemIndex,p]of list.entries()){let values=[p.code,[p.name,p.group?'Grupo: '+p.group:'',p.note?'Obs.: '+p.note:''].filter(Boolean).join('\n'),p.dimensions||'-',num(p.planned),p.unit,num(p.remaining),p.operations],cells=values.map((v,i)=>wrap(v,widths[i]-10,8.2)),height=Math.max(...cells.map(a=>a.length)),offset=0;while(offset<height){let reserve=itemIndex>=list.length-3?90:0,fit=Math.floor((y-B-10-reserve)/lh);if(fit<1){newPage();tableHead();fit=Math.floor((y-B-10-reserve)/lh)}let count=Math.min(fit,height-offset),rowHeight=count*lh+10,x=L;for(let i=0;i<cells.length;i++){let lines=cells[i].slice(offset,offset+count);if(offset&&i===0&&!lines.length)lines=[p.code+' (cont.)'];lines.forEach((s,j)=>text(s,x+5,y-13-j*lh,8.2));x+=widths[i]}page.drawLine({start:{x:L,y:y-rowHeight},end:{x:R,y:y-rowHeight},thickness:.5,color:line});y-=rowHeight;offset+=count;if(offset<height){newPage();tableHead()}}}
 y-=18;block('Leitura da coluna Falta','Quantidade ainda não concluída em todas as operações previstas para a peça.');const units=new Map();for(let p of list){let t=units.get(p.unit)||{planned:0,remaining:0};t.planned+=p.planned;t.remaining+=p.remaining;units.set(p.unit,t)}for(let [u,t]of units)block('Total em '+u,'Previsto '+num(t.planned)+' | Falta '+num(t.remaining));if(y<B+60)newPage();y-=8;page.drawLine({start:{x:L,y},end:{x:L+240,y},thickness:.5,color:line});page.drawLine({start:{x:R-240,y},end:{x:R,y},thickness:.5,color:line});text('Responsável pela emissão',L,y-13,8,false,muted);text('Responsável pelo recebimento na fábrica',R-240,y-13,8,false,muted);
 for(let [i,p]of pdf.getPages().entries()){p.drawLine({start:{x:L,y:28},end:{x:R,y:28},thickness:.5,color:line});p.drawText('Engefex | '+number+' | '+list.length+' itens',{x:L,y:15,size:7,font,color:muted});let footer='Página '+(i+1)+' de '+pdf.getPageCount();p.drawText(footer,{x:R-font.widthOfTextAtSize(footer,7),y:15,size:7,font,color:muted})}
 await Promise.all(jobs);pdf.setTitle('Ordem de fabricação - '+project.name);pdf.setAuthor('Engefex Engenharia & Estruturas Metálicas');return pdf.save();
}
async function download(order,project,opts={}){let response=await fetch(new URL('engefex-logo.png',root.location.href));if(!response.ok)throw Error('Não foi possível carregar o logotipo.');let bytes=await generate(order,project,{...opts,logoBytes:new Uint8Array(await response.arrayBuffer())}),blob=new Blob([bytes],{type:'application/pdf'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=('OF_'+(project.code||project.name)+'_'+new Date().toISOString().slice(0,10)).replace(/[^\w.\-]/g,'_')+'.pdf';a.click();setTimeout(()=>URL.revokeObjectURL(url),60000)}
root.EngefexFactoryPDF={rows,generate,download};
})(typeof window==='undefined'?globalThis:window);
